-- Migración 2 (parte) · geo_semilla_municipios_5 — municipios de los departamentos 70–99
-- (filas de supabase/seed/geo.sql sin cambios; separado de `geo` por tamaño). Cada parte contiene
-- departamentos completos, así la FK diferida codigo_geometria se resuelve dentro de la parte.

on conflict (codigo) do update set
  departamento_codigo = excluded.departamento_codigo,
  nombre = excluded.nombre,
  nombre_normalizado = excluded.nombre_normalizado,
  tipo = excluded.tipo,
  es_capital = excluded.es_capital,
  lon = excluded.lon,
  lat = excluded.lat,
  codigo_geometria = excluded.codigo_geometria,
  bbox = excluded.bbox;

-- Con todas las capitales cargadas ya puede existir la FK de la capital departamental
-- (Cundinamarca → 11001 Bogotá pertenece a otro departamento).
alter table public.departamentos
  add constraint departamentos_capital_codigo_fkey foreign key (capital_codigo)
  references public.municipios (codigo) on delete restrict deferrable initially deferred;

do $$ begin
  assert (select count(*) from public.paises) = 250, 'paises: se esperaban 250 filas';
  assert (select count(*) from public.departamentos) = 33, 'departamentos: se esperaban 33 filas';
  assert (select count(*) from public.municipios) = 1122, 'municipios: se esperaban 1122 filas';
  assert (select count(*) from public.municipios where codigo_geometria <> codigo) = 4,
         'municipios: se esperaban 4 códigos de geometría sustitutos';
  assert (select count(*) from public.municipios where es_capital) = 32,
         'municipios: se esperaban 32 capitales propias (Cundinamarca usa Bogotá)';
end $$;
